#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=7
ENV_FILE=".chrome-webstore.env"
EXTENSION_ID="dgkpaaeifngfeelldljpdlnmacdpceba"

banner "Chrome Web Store publish auth"

say "This sets up a Google Cloud service account so CI can upload Eventuate"
say "to the Chrome Web Store the same way it already submits to Firefox AMO."
say "Screenshots stay manual; this only covers the package."
note "Local values go to $ENV_FILE (do not commit it)."
note "Extension ID is fixed: $EXTENSION_ID"
pause "Ready?"

# ── Stage 1 ───────────────────────────────────────────────────────────────
stage "Google Cloud project"
say "CI needs a Google Cloud project that owns the Chrome Web Store API."
open_url "https://console.cloud.google.com/projectselector2/home/dashboard"
step "Create a new project (suggested name: eventuate-chrome-webstore) or select an existing one you control."
step "Stay signed in as the Google account that owns the Chrome Web Store listing."
pause "Project selected?"

# ── Stage 2 ───────────────────────────────────────────────────────────────
stage "Enable Chrome Web Store API"
say "Turn on the API for this project."
open_url "https://console.cloud.google.com/apis/library/chromewebstore.googleapis.com"
step "Confirm the project in the top bar is the one from the previous stage."
step "Click Enable (or Manage if it is already enabled)."
pause "API enabled?"

# ── Stage 3 ───────────────────────────────────────────────────────────────
stage "Create a service account"
say "Create a robot identity. No IAM roles are required on the Google Cloud side."
open_url "https://console.cloud.google.com/iam-admin/serviceaccounts"
step "Confirm the same project is selected."
step "Click Create service account."
step "Name it something like eventuate-cws-publisher."
step "Skip granting optional project access / IAM roles — click Done."
pause "Service account created?"

# ── Stage 4 ───────────────────────────────────────────────────────────────
stage "Download a JSON key"
say "CI will authenticate with a JSON key file for that service account."
warn "Treat this file like a password. Do not commit it."
open_url "https://console.cloud.google.com/iam-admin/serviceaccounts"
step "Open the service account you just created."
step "Keys → Add key → Create new key → JSON → Create."
step "Save the downloaded file somewhere outside the git repo (for example ~/Downloads/)."
ask KEY_PATH "Absolute path to the downloaded JSON key:"
KEY_PATH="${KEY_PATH/#\~/$HOME}"
if [[ ! -f "$KEY_PATH" ]]; then
  warn "No file at $KEY_PATH"
  ask KEY_PATH "Absolute path to the downloaded JSON key:"
  KEY_PATH="${KEY_PATH/#\~/$HOME}"
fi
if [[ ! -f "$KEY_PATH" ]]; then
  warn "Still no file at $KEY_PATH — aborting this stage."
  exit 1
fi
if ! command -v jq >/dev/null 2>&1; then
  warn "jq is required to minify and validate the key JSON."
  exit 1
fi
CHROME_WEBSTORE_SERVICE_ACCOUNT_JSON=$(jq -c . "$KEY_PATH")
SERVICE_ACCOUNT_EMAIL=$(jq -r .client_email "$KEY_PATH")
if [[ -z "$SERVICE_ACCOUNT_EMAIL" || "$SERVICE_ACCOUNT_EMAIL" == null ]]; then
  warn "That file does not look like a service account key (missing client_email)."
  exit 1
fi
write_env CHROME_WEBSTORE_SERVICE_ACCOUNT_JSON "$CHROME_WEBSTORE_SERVICE_ACCOUNT_JSON"
write_env SERVICE_ACCOUNT_EMAIL "$SERVICE_ACCOUNT_EMAIL"
note "Service account email: $SERVICE_ACCOUNT_EMAIL"

# ── Stage 5 ───────────────────────────────────────────────────────────────
stage "Link the service account in the Chrome Web Store"
say "Google only allows one service account per publisher. Paste the email into the dashboard."
open_url "https://chrome.google.com/webstore/devconsole"
step "Open Account (sometimes labelled under the publisher account settings)."
step "Find the service account field and paste: $SERVICE_ACCOUNT_EMAIL"
step "Save."
note "Docs: https://developer.chrome.com/docs/webstore/service-accounts"
pause "Service account linked?"

# ── Stage 6 ───────────────────────────────────────────────────────────────
stage "Publisher ID"
say "The API needs your publisher ID (not the extension ID)."
open_url "https://chrome.google.com/webstore/devconsole"
step "Open Publisher → Settings (or Account settings)."
step "Copy the Publisher ID shown there."
note "Extension ID stays $EXTENSION_ID — do not paste that here."
ask CHROME_WEBSTORE_PUBLISHER_ID "Paste the Publisher ID:"
if [[ -z "$CHROME_WEBSTORE_PUBLISHER_ID" ]]; then
  warn "Publisher ID is required."
  exit 1
fi
write_env CHROME_WEBSTORE_PUBLISHER_ID "$CHROME_WEBSTORE_PUBLISHER_ID"

# ── Stage 7 ───────────────────────────────────────────────────────────────
stage "Write GitHub secrets and variables"
say "CI will read these from the johnsyweb/eventuate repository."
if confirm "Set GitHub secret and variable now with gh"; then
  set_secret CHROME_WEBSTORE_SERVICE_ACCOUNT_JSON "$CHROME_WEBSTORE_SERVICE_ACCOUNT_JSON"
  set_var CHROME_WEBSTORE_PUBLISHER_ID "$CHROME_WEBSTORE_PUBLISHER_ID"
else
  SKIPPED+=("GitHub secret CHROME_WEBSTORE_SERVICE_ACCOUNT_JSON")
  SKIPPED+=("GitHub variable CHROME_WEBSTORE_PUBLISHER_ID")
  note "Later:"
  note "  gh secret set CHROME_WEBSTORE_SERVICE_ACCOUNT_JSON < $ENV_FILE  # or paste minified JSON"
  note "  gh variable set CHROME_WEBSTORE_PUBLISHER_ID --body \"$CHROME_WEBSTORE_PUBLISHER_ID\""
fi
note "You can delete the downloaded key file from Downloads once GitHub has the secret."
if confirm "Delete the local key file at $KEY_PATH"; then
  rm -f "$KEY_PATH"
  printf '  %s✓ deleted%s %s\n' "$GREEN" "$RESET" "$KEY_PATH"
fi

finish

say "Next: wire cssnr/webstore-publish-action into the release job (extension"
say "$EXTENSION_ID, publish: default, zip: eventuate-chromium.zip)."
